[{"order":1,"type":"heading","text":"Handling Sessions and Cookies in Flask"},{"order":2,"type":"paragraph","text":"Web applications often need to remember user data across multiple requests. Flask provides two primary mechanisms for this purpose: Cookies, which are stored on the client side, and Sessions, which are signed and stored securely on the client side using cookies as the transport mechanism."},{"order":3,"type":"subheading","text":"Understanding Cookies in Flask"},{"order":4,"type":"paragraph","text":"Cookies are small pieces of data sent from a website and stored on the user's web browser while the user is browsing. In Flask, you set cookies using the response object and read them using the request object."},{"order":5,"type":"code","text":"from flask import Flask, make_response, request

app = Flask(__name__)

@app.route("/set_cookie")
def set_cookie():
    resp = make_response("Cookie is set")
    resp.set_cookie("username", "flask_user", max_age=60*60*24)
    return resp

@app.route("/get_cookie")
def get_cookie():
    username = request.cookies.get("username", "Guest")
    return f"Hello, {username}!""},{"order":6,"type":"subheading","text":"Working with Sessions in Flask"},{"order":7,"type":"paragraph","text":"Unlike basic cookies, Flask sessions allow you to store specific data for a user across requests. Flask's session object keeps data secure by signing it cryptographically using a secret key. This means users can view the session data if they inspect the cookie, but they cannot modify it without knowing your secret key."},{"order":8,"type":"code","text":"from flask import Flask, session, redirect, url_for, request

app = Flask(__name__)
app.secret_key = "your_secure_random_secret_key"

@app.route("/login", methods=["POST"])
def login():
    session["username"] = request.form.get("username")
    return redirect(url_for("profile"))

@app.route("/profile")
def profile():
    if "username" in session:
        return f"Logged in as {session["username"]}"
    return "You are not logged in"

@app.route("/logout")
def logout():
    session.pop("username", None)
    return redirect(url_for("profile"))"},{"order":9,"type":"subheading","text":"Best Practices for Sessions and Cookies"},{"order":10,"type":"bullet_point","text":"Always set a strong, unpredictable secret_key for your Flask application to prevent session tampering."},{"order":11,"type":"bullet_point","text":"Do not store sensitive information like raw passwords inside cookies or unencrypted session payloads."},{"order":12,"type":"bullet_point","text":"Use secure flags (secure=True and httponly=True) when setting production cookies to protect against cross-site scripting (XSS) and man-in-the-middle attacks."}]
